<script setup lang="ts">
import { nextTick, onMounted, onUnmounted, ref } from 'vue'
import { myMerchants, type MerchantWorkspace } from '../campus-merchant/workflow-api'
import { redeemCoupon, merchantRedemptions, type Redemption } from './api'
import PaginationBar from '../../campus-shared/PaginationBar.vue'
const stores = ref<MerchantWorkspace[]>([]), merchant = ref(''), rows = ref<Redemption[]>([]), storePage = ref(1), storeTotal = ref(0), page = ref(1), total = ref(0), code = ref(''), message = ref(''), busy = ref(false), camera = ref(false), video = ref<HTMLVideoElement | null>(null)
let stream: MediaStream | null = null, disposed = false, frame = 0
type Detector = { detect(source: HTMLVideoElement): Promise<{ rawValue: string }[]> }
const detectorClass = (window as unknown as { BarcodeDetector?: new (options: { formats: string[] }) => Detector }).BarcodeDetector
function stopCamera() { cancelAnimationFrame(frame); stream?.getTracks().forEach(track => track.stop()); stream = null; camera.value = false }
async function startCamera() { if (!detectorClass || !navigator.mediaDevices?.getUserMedia) { message.value = '当前浏览器不支持扫码，请粘贴扫码结果或核销码。'; return } try { camera.value = true; await nextTick(); stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' }, audio: false }); if (disposed || !video.value) { stopCamera(); return } video.value.srcObject = stream; await video.value.play(); const detector = new detectorClass({ formats: ['qr_code'] }); const scan = async () => { if (!camera.value || !video.value) return; try { const result = await detector.detect(video.value); if (result[0]) { code.value = result[0].rawValue; stopCamera(); message.value = '已识别核销凭据，请确认门店后提交。'; return } } catch { /* a not-yet-ready frame can be retried */ } frame = requestAnimationFrame(() => void scan()) }; void scan() } catch { stopCamera(); message.value = '摄像头暂不可用，请粘贴核销码。' } }
onUnmounted(() => { disposed = true; stopCamera(); code.value = '' })
async function load(next = 1) { if (!merchant.value) return; busy.value = true; try { const data = await merchantRedemptions(merchant.value, next); rows.value = data.items; page.value = data.page; total.value = data.total } catch (error) { message.value = error instanceof Error ? error.message : '记录加载失败' } finally { busy.value = false } }
async function loadStores(next = 1) { busy.value = true; try { const data = await myMerchants(next); stores.value = data.items; storePage.value = data.page; storeTotal.value = data.total; merchant.value = data.items[0]?.id ?? ''; if (merchant.value) await load() } catch (error) { message.value = error instanceof Error ? error.message : '门店加载失败' } finally { busy.value = false } }
onMounted(() => loadStores())
async function redeem() { busy.value = true; message.value = ''; try { await redeemCoupon(merchant.value, code.value.trim()); code.value = ''; stopCamera(); await load(); message.value = '到店核销成功。' } catch (error) { message.value = error instanceof Error ? error.message : '核销失败' } finally { busy.value = false } }
</script>
<template><section><RouterLink class="text-link" to="/merchant">← 返回商家工作台</RouterLink><h1>到店核销</h1><label for="redemptionMerchant">核销门店</label><select id="redemptionMerchant" v-model="merchant" :disabled="busy" @change="code = ''; stopCamera(); load()"><option v-for="store in stores" :key="store.id" :value="store.id">{{ store.name }}</option></select><PaginationBar :page="storePage" :size="20" :total="storeTotal" :disabled="busy" @change="loadStores" /><p class="muted">请核对顾客出示的短时二维码与当前门店。暂停门店不能核销。</p>
  <form @submit.prevent="redeem"><label for="redemptionCode">核销码或扫码结果</label><textarea id="redemptionCode" v-model="code" required maxlength="80" autocomplete="off" autocapitalize="off" spellcheck="false" rows="3" :disabled="busy" /><div class="button-row"><button :disabled="busy || !merchant || !code.trim()">确认核销</button><button type="button" class="secondary" :disabled="busy || camera" @click="startCamera">使用摄像头扫码</button><button v-if="camera" type="button" class="secondary" @click="stopCamera">关闭摄像头</button></div></form><video v-if="camera" ref="video" class="scanner-video" playsinline muted /><p v-if="message" role="status">{{ message }}</p>
  <h2>本店核销记录</h2><div class="table-scroll spaced"><table><thead><tr><th>核销编号</th><th>券编号</th><th>操作人</th><th>时间</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ row.id }}</td><td>{{ row.claimId }}</td><td>{{ row.operatorId }}</td><td>{{ new Date(row.redeemedAt).toLocaleString() }}</td></tr></tbody></table></div><PaginationBar :page="page" :size="20" :total="total" :disabled="busy" @change="load" />
</section></template>
